export const init=()=>{const button=document.getElementById("learnlingo-copy-prompt");const textarea=document.getElementById("learnlingo-brand-prompt");if(!button||!textarea){return}button.addEventListener("click",async()=>{try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(textarea.value);return}}catch(error){}textarea.focus();textarea.select();document.execCommand("copy")})};